import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(reader.readLine())
    val n = st.nextToken().toInt()
    val c1 = st.nextToken().toLong()
    val c2 = st.nextToken().toLong()
    val s = reader.readLine().trim()

    val adults = mutableListOf<Int>()
    for (i in s.indices) {
        if (s[i] == '1') adults.add(i)
    }

    val m = adults.size
    val dp = LongArray(m + 1)
    val INF = Long.MAX_VALUE / 4
    for (i in 1..m) dp[i] = INF

    for (i in 0 until m) {
        if (dp[i] == INF) continue
        var j = i
        while (j < m) {
            val groupSize = adults[j] - adults[i] + 1
            val cost = c1 + c2 * (groupSize - 1L) * (groupSize - 1L)
            if (dp[i] + cost < dp[j + 1]) {
                dp[j + 1] = dp[i] + cost
            }
            j++
        }
    }

    println(dp[m])
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(reader.readLine())
    val n = st.nextToken().toInt()
    val c1 = st.nextToken().toLong()
    val c2 = st.nextToken().toLong()
    val s = reader.readLine().trim()

    val adults = s.count { it == '1' }
    val pupils = n - adults

    // Precompute cost for group sizes 1..n
    val cost = LongArray(n + 1)
    for (x in 1..n) {
        val diff = (x - 1).toLong()
        cost[x] = c1 + c2 * diff * diff
    }

    val INF = Long.MAX_VALUE / 4
    val dp = Array(adults + 1) { LongArray(pupils + 1) { INF } }
    dp[0][0] = 0L

    for (a in 0..adults) {
        for (p in 0..pupils) {
            val cur = dp[a][p]
            if (cur == INF) continue
            // form group with ga adults and gp pupils
            var ga = 1
            while (a + ga <= adults) {
                val maxGp = pupils - p
                if (maxGp < 0) break
                var gp = 0
                while (gp <= maxGp) {
                    val x = ga + gp
                    val next = cur + cost[x]
                    val na = a + ga
                    val np = p + gp
                    if (next < dp[na][np]) dp[na][np] = next
                    gp++
                }
                ga++
            }
        }
    }

    println(dp[adults][pupils])
}

