import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer
import kotlin.math.*

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st1 = StringTokenizer(br.readLine())
    val n = st1.nextToken().toInt()
    val c1 = st1.nextToken().toLong()
    val c2 = st1.nextToken().toLong()
    val s = br.readLine().trim()

    val adults = s.count { it == '1' }
    val pupils = n - adults

    // If no pupils, each adult must be in some group; we can group all adults together
    // but we must still obey "at least one adult per group", which is always true.
    // The DP below already handles this case, but we keep counts for clarity.

    // dp[a][p] = minimal cost to cover a adults and p pupils
    // But n can be 200000, so 2D DP is impossible.
    // We observe that only total group size matters, and each group must contain >=1 adult.
    // Let’s think in terms of adults: each group has at least 1 adult, so number of groups <= adults.
    // Pupils can be distributed arbitrarily among groups.
    //
    // Let g be number of groups (1..adults).
    // We must partition adults into g groups, each having at least 1 adult.
    // So adults = g + extraAdults, where extraAdults >=0.
    // Pupils can be distributed among g groups too.
    // Total people per group sum to n.
    // Cost only depends on group sizes: sum_i [c1 + c2*(xi-1)^2] = g*c1 + c2*sum_i (xi-1)^2.
    // For fixed g, to minimize sum (xi-1)^2 given sum xi = n and xi>=1 and each group has at least 1 adult.
    // But we also need at least 1 adult per group; however, pupils/adults are indistinguishable in cost.
    // Since adults>=g, we can always assign 1 adult per group first, remaining people (adults+pupils - g) can be any.
    // So constraint reduces to xi>=1 and sum xi = n, which is classic: sum (xi-1)^2 minimized when xi are as equal as possible.
    //
    // Let yi = xi-1 >=0, sum yi = n-g.
    // Minimize sum yi^2: distribute as evenly as possible: some groups get floor, some ceil.
    // Let base = (n-g)/g, rem = (n-g)%g.
    // Then rem groups have (base+1), others have base.
    // sum yi^2 = rem*(base+1)^2 + (g-rem)*base*base.
    //
    // So for each g from 1..adults, compute cost and take min.

    val totalPeople = n.toLong()
    val adultsCount = adults

    var answer = Long.MAX_VALUE

    for (g in 1..adultsCount) {
        val gL = g.toLong()
        val remaining = totalPeople - gL // sum of yi
        if (remaining < 0) continue
        val base = remaining / gL
        val rem = (remaining % gL).toInt()
        val baseLong = base
        val baseSq = baseLong * baseLong
        val basePlus1Sq = (baseLong + 1) * (baseLong + 1)
        val sumYSq = baseSq * (gL - rem) + basePlus1Sq * rem
        val cost = gL * c1 + c2 * sumYSq
        if (cost < answer) answer = cost
    }

    println(answer)
}
