import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(reader.readLine())
    val n = st.nextToken().toInt()
    val c1 = st.nextToken().toLong()
    val c2 = st.nextToken().toLong()
    val s = reader.readLine().trim()

    val adults = s.count { it == '1' }
    val pupils = n - adults

    // dpA[a] = minimal cost to cover 'a' adults, no pupils yet
    val dpA = LongArray(adults + 1) { Long.MAX_VALUE }
    dpA[0] = 0L

    for (a in 1..adults) {
        var k = 1
        while (k <= a) {
            val cost = c1 + c2 * (k - 1L) * (k - 1L)
            if (dpA[a - k] != Long.MAX_VALUE) {
                val candidate = dpA[a - k] + cost
                if (candidate < dpA[a]) dpA[a] = candidate
            }
            k++
        }
    }

    var answer = Long.MAX_VALUE

    // For each possible number of adult-only groups gA, compute cost and remaining adults
    // We iterate over total adults used in adult-only groups: aUsed
    for (aUsed in 0..adults) {
        val costAdultsOnly = dpA[aUsed]
        if (costAdultsOnly == Long.MAX_VALUE) continue
        val remainingAdults = adults - aUsed
        if (remainingAdults == 0) {
            // no adults left, so no pupils can be served unless pupils == 0
            if (pupils == 0 && costAdultsOnly < answer) {
                answer = costAdultsOnly
            }
            continue
        }

        // Now we must partition pupils into groups, each with at least 1 adult.
        // Let g be number of mixed groups, 1 <= g <= remainingAdults and g <= pupils (if pupils>0)
        if (pupils == 0) {
            // no pupils, just adults-only groups already counted
            if (costAdultsOnly < answer) answer = costAdultsOnly
            continue
        }

        val maxGroups = minOf(remainingAdults, pupils)
        var g = 1
        while (g <= maxGroups) {
            // distribute pupils among g groups: each group has size >=2 (1 adult + at least 1 pupil)
            // minimal size is 2, so total people in mixed groups >= 2*g
            // we only care about pupils distribution; adults per group at least 1
            // Let each group have size x_i >= 2, sum x_i = g + pupilsUsed (since exactly one adult per group minimal)
            // But we can add extra adults to some groups; that only increases cost, so we avoid extra adults.
            // So each mixed group has exactly 1 adult, and pupils are distributed: each group gets at least 1 pupil.
            // So pupils = g + extra, where extra >=0, distribute extra among g groups.
            // To minimize sum (x_i-1)^2 = sum (p_i)^2 where p_i is pupils in group i,
            // we distribute pupils as evenly as possible.
            val base = pupils / g
            val rem = pupils % g
            // p_i = base+1 for rem groups, base for others
            // group size x_i = 1 adult + p_i pupils
            var costMixed = 0L
            // rem groups with base+1 pupils
            if (base + 1 >= 1) {
                val x = 1L + (base + 1).toLong()
                val term = c1 + c2 * (x - 1L) * (x - 1L)
                costMixed += term * rem
            } else {
                costMixed = Long.MAX_VALUE
            }
            // (g-rem) groups with base pupils
            if (costMixed < Long.MAX_VALUE && base >= 1) {
                val x = 1L + base.toLong()
                val term = c1 + c2 * (x - 1L) * (x - 1L)
                costMixed += term * (g - rem)
            } else if (base < 1) {
                costMixed = Long.MAX_VALUE
            }

            if (costMixed < Long.MAX_VALUE) {
                val totalCost = costAdultsOnly + costMixed
                if (totalCost < answer) answer = totalCost
            }
            g++
        }
    }

    println(answer)
}

