    val INF = Long.MAX_VALUE / 4
    val dp = LongArray(m + 1) { INF }
    dp[0] = 0L

    for (i in 0 until m) {
        // group starting at adults[i], ending at adults[j]
        var j = i
        while (j < m) {
            val left = adults[i]
            val right = adults[j]
            val size = right - left + 1
            val cost = c1 + c2 * (size - 1L) * (size - 1L)
            if (dp[i] + cost < dp[j + 1]) {
                dp[j + 1] = dp[i] + cost
            }
            j++
        }
    }

